record.field:
companies = env['res.company'].search([('misa_inbot_jwt_token', '!=', False)])
for comp in companies:
    orgs = env['misa.organization'].search([('company_id', '=', comp.id)])
    for org in orgs:
        try:
            wiz = env['misa.inbot.sync.wizard'].create({
                'company_id': comp.id,
                'organization_id': org.id,
                'invoice_direction': 'in_invoice',
                'from_date': (datetime.date.today() - datetime.timedelta(days=2)),
                'to_date': datetime.date.today(),
                'is_filter_inv_date': False,
                'take': 100,
            })
            wiz.action_sync_invoices()
        except Exception as e:
            pass
